code.source:
#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> v = {10, 20, 30};
    v.insert(v.begin() + 1, 99);
    v.erase(v.begin());
    for (int x : v) {
        cout << x << " ";
    }
    cout << endl;
    return 0;
}

#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> v = {40, 10, 30, 20};
    sort(v.begin(), v.end());
    for (int x : v) {
        cout << x << " ";
    }
    cout << endl;
    auto it = find(v.begin(), v.end(), 30);
    cout << (it - v.begin()) << endl;
    return 0;
}

